}

type Settings = {name: string; email: string; avatar: string; language: string; timezone: string; twoFactor: boolean; news: boolean; alerts: boolean; digest: boolean};
const initial: Settings = {name: 'Александр Иванов', email: 'alex.ivanov@gmail.com', avatar: '', language: 'ru', timezone: 'Europe/Moscow', twoFactor: false, news: true, alerts: true, digest: false};
const storageKey = 'orbit-profile-settings-v1';
function readSettings(): Settings {
 try {const data = JSON.parse(localStorage.getItem(storageKey) || 'null'); if (data && Object.keys(initial).every(key => typeof data[key] === typeof initial[key as keyof Settings])) return {...initial, ...data};} catch {}
 return initial;
}
const languages = [{value:'ru', content:'Русский'}, {value:'en', content:'English'}, {value:'de', content:'Deutsch'}, {value:'es', content:'Español'}, {value:'fr', content:'Français'}];
const timezones = [
 {value:'Europe/Moscow',content:'(UTC+03:00) Москва'}, {value:'Europe/Kaliningrad',content:'(UTC+02:00) Калининград'}, {value:'Europe/Samara',content:'(UTC+04:00) Самара'}, {value:'Asia/Yekaterinburg',content:'(UTC+05:00) Екатеринбург'}, {value:'Asia/Novosibirsk',content:'(UTC+07:00) Новосибирск'}, {value:'Asia/Vladivostok',content:'(UTC+10:00) Владивосток'}, {value:'UTC',content:'(UTC+00:00) Всемирное время'}, {value:'Europe/Berlin',content:'Берлин — Europe/Berlin'}, {value:'America/New_York',content:'Нью-Йорк — America/New_York'}, {value:'Asia/Almaty',content:'(UTC+05:00) Алматы'},
];
function Avatar({settings, small = false}: {settings: Settings; small?: boolean}) {
 const initials = settings.name.trim().split(/\\s+/).filter(Boolean).slice(0, 2).map(s => s[0]).join('').toUpperCase() || 'А';
 return <div className={"'`avatar ${small ? '"'avatar-small' : ''}"'`}>{settings.avatar ? <img src={settings.avatar} alt="Аватар профиля"/> : <span>{initials}</span>}</div>;
}
function SectionHeading({icon, title, description}: {icon: IconName; title: string; description?: string}) {
 return <div className="section-heading"><div className="section-icon"><Icon name={icon} size={19}/></div><div><h2>{title}</h2>{description && <p>{description}</p>}</div></div>;
}
export function App() {
 const [saved, setSaved] = useState<Settings>(readSettings);
 const [form, setForm] = useState<Settings>(saved);
 const [errors, setErrors] = useState<Record<string, string>>({});
 const [toast, setToast] = useState('"'');
 const [sidebarOpen, setSidebarOpen] = useState(false);
 const [helpOpen, setHelpOpen] = useState(false);
 const [tab, setTab] = useState('profile');
 const fileRef = useRef<HTMLInputElement>(null);
 const toastTimer = useRef<ReturnType<typeof setTimeout>>();
 const dirty = JSON.stringify(form) "'!== JSON.stringify(saved);
 function update<K extends keyof Settings>(key: K, value: Settings[K]) {setForm(f => ({...f, [key]: value})); setErrors(e => ({...e, [key]: '"''}));}
 function notify(message: string) {setToast(message); clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(''), 4500);}
 async function upload(e: ChangeEvent<HTMLInputElement>) {
  const file = e.target.files?.[0]; e.target.value = ''; if ("'!file) return;
  if (!['"'image/jpeg','image/png','image/webp'].includes(file.type)) {setErrors(x => ({...x, avatar: 'Выберите изображение JPG, PNG или WebP.'})); return;}
  if (file.size > 5 * 1024 * 1024) {setErrors(x => ({...x, avatar: 'Размер файла не должен превышать 5 МБ.'})); return;}
  try {
   const bitmap = await createImageBitmap(file);
   const canvas = document.createElement('canvas'); canvas.width = canvas.height = 256;
   const context = canvas.getContext('2d'); if ("'!context) throw new Error();
   const crop = Math.min(bitmap.width, bitmap.height);
   context.drawImage(bitmap, (bitmap.width-crop)/2, (bitmap.height-crop)/2, crop, crop, 0, 0, 256, 256); bitmap.close();
   update('"'avatar', canvas.toDataURL('image/webp', .85));
  } catch {setErrors(x => ({...x, avatar: 'Не удалось открыть изображение. Попробуйте другой файл.'}));}
 }
 function save(e: FormEvent) {
  e.preventDefault(); const nextErrors: Record<string,string> = {};
  if ("'!form.name.trim()) nextErrors.name = '"'Введите ваше имя';
  if ("'!/''^[''^'"\\s@]+@["'^'"\\s@]+\\.["'^'"\\s@]+"'$/.test(form.email.trim())) nextErrors.email = '"'Введите корректный email';
  setErrors(nextErrors); if (Object.keys(nextErrors).length) {document.getElementById(nextErrors.name ? 'name' : 'email')?.focus(); return;}
  const cleaned = {...form, name: form.name.trim(), email: form.email.trim()};
  try {localStorage.setItem(storageKey, JSON.stringify(cleaned)); setForm(cleaned); setSaved(cleaned); notify('Настройки успешно сохранены');} catch {notify('Не удалось сохранить настройки. Проверьте доступ к хранилищу браузера.');}
 }
 function goTo(id: string) {setTab(id); document.getElementById(id)?.scrollIntoView({behavior: 'smooth', block: 'center'}); setSidebarOpen(false);}
 return <div className=\"app-shell\">
  {sidebarOpen && <div className=\"sidebar-overlay\" onClick={() => setSidebarOpen(false)}/>}
  <aside className={"'`sidebar ${sidebarOpen ? '"'is-open' : ''}"'`}>
   <a className="brand" href="#" aria-label="Orbit — главная"><span className="brand-symbol"><span/></span>orbit<span className="brand-dot">.</span></a>
   <div className="workspace"><div className="workspace-icon">А</div><div><strong>Моё пространство</strong><span>Личный аккаунт</span></div><span className="workspace-dots">···</span></div>
   <div className="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div>
   <nav className="primary-nav" aria-label="Основная навигация">
    <a href="#profile" onClick={() => goTo('"'profile')}><Icon name=\"grid\"/>Обзор</a>
    <a href=\"#preferences\" onClick={() => goTo('preferences')}><Icon name=\"globe\"/>Предпочтения</a>
    <a href=\"#security\" onClick={() => goTo('security')}><Icon name=\"shield\"/>Безопасность</a>
    <a href=\"#notifications\" onClick={() => goTo('notifications')}><Icon name=\"bell\"/>Уведомления</a>
    <div className=\"nav-divider\"/>
    <a className=\"active\" href=\"#profile\" onClick={() => goTo('profile')} aria-current=\"page\"><Icon name=\"settings\"/>Настройки<span className=\"active-dot\"/></a>
   </nav>
   <div className=\"sidebar-bottom\"><button className=\"help-link\" onClick={() => setHelpOpen(true)}><Icon name=\"help\"/>Помощь и поддержка<Icon name=\"arrow\" size={16}/></button><div className=\"sidebar-account\"><Avatar settings={saved} small/><div><strong>{saved.name || 'Ваш профиль'}</strong><span>Личный аккаунт</span></div><Icon name=\"chevron\" size={16}/></div></div>
  </aside>
  <div className=\"main-shell\">
   <header className=\"topbar\"><div className=\"breadcrumb\"><button className=\"mobile-menu icon-button\" aria-label=\"Открыть меню\" onClick={() => setSidebarOpen("'!sidebarOpen)}><Icon name="menu"/></button><span>Рабочее пространство</span><Icon name="chevron" size={13}/><strong>Настройки</strong></div><div className="topbar-right"><span className="personal-label"><span/>Личное пространство</span><span className="topbar-divider"/><button className="icon-button" aria-label="Настройки уведомлений" onClick={() => goTo('"'notifications')}><Icon name=\"bell\"/></button><Avatar settings={saved} small/></div></header>
   <main className=\"content\">
    <div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШ АККАУНТ</div><h1>Настройки профиля</h1><p>Всё, чтобы сделать пространство своим.</p></div><span className=\"account-badge\"><Icon name=\"user\" size={14}/>Личный аккаунт</span></div>
    <div className=\"tabs\" role=\"navigation\" aria-label=\"Разделы настроек\">{[{id:'profile',label:'Мой профиль',icon:'user'}, {id:'security',label:'Безопасность',icon:'shield'}, {id:'notifications',label:'Уведомления',icon:'bell'}].map(item => <button key={item.id} className={tab === item.id ? 'selected' : ''} onClick={() => goTo(item.id)}><Icon name={item.icon as IconName} size={17}/>{item.label}</button>)}</div>
    <div className=\"settings-layout\">
     <form className=\"settings-card\" onSubmit={save} noValidate>
      <section id=\"profile\" className=\"form-section\"><SectionHeading icon=\"user\" title=\"Личная информация\" description=\"Как вас будут видеть другие участники.\"/>
       <div className=\"avatar-field\"><div className=\"avatar-wrapper\"><Avatar settings={form}/><button type=\"button\" className=\"camera-button\" onClick={() => fileRef.current?.click()} aria-label=\"Загрузить аватар\"><Icon name=\"camera\" size={13}/></button></div><div className=\"avatar-actions\"><div><Button size=\"m\" onClick={() => fileRef.current?.click()}><Icon name=\"upload\" size={15}/>Загрузить фото</Button>{form.avatar && <button type=\"button\" className=\"text-button\" onClick={() => update('avatar','')}>Удалить</button>}</div><p>JPG, PNG или WebP. Не более 5 МБ.</p></div><input hidden ref={fileRef} type=\"file\" accept=\"image/jpeg,image/png,image/webp\" onChange={upload} aria-label=\"Файл аватара\"/></div>
       {errors.avatar && <p className=\"field-error\" role=\"alert\">{errors.avatar}</p>}
