  if (!['"'image/jpeg','image/png','image/webp'].includes(file.type)) {setErrors(x => ({...x, avatar: 'Выберите изображение JPG, PNG или WebP.'})); return;}
  if (file.size > 5 * 1024 * 1024) {setErrors(x => ({...x, avatar: 'Размер файла не должен превышать 5 МБ.'})); return;}
  try {
   const bitmap = await createImageBitmap(file);
   const canvas = document.createElement('canvas'); canvas.width = canvas.height = 256;
   const context = canvas.getContext('2d'); if ("'!context) throw new Error();
   const crop = Math.min(bitmap.width, bitmap.height);
