type Settings = {name: string; email: string; avatar: string; language: string; timezone: string; twoFactor: boolean; news: boolean; alerts: boolean; digest: boolean};
const initial: Settings = {name: 'Александр Иванов', email: 'alex.ivanov@gmail.com', avatar: '', language: 'ru', timezone: 'Europe/Moscow', twoFactor: false, news: true, alerts: true, digest: false};
const storageKey = 'orbit-profile-settings-v1';
function readSettings(): Settings {
 try {const data = JSON.parse(localStorage.getItem(storageKey) || 'null'); if (data && Object.keys(initial).every(key => typeof data[key] === typeof initial[key as keyof Settings])) return {...initial, ...data};} catch {}
 return initial;
}
const languages = [{value:'ru', content:'Русский'}, {value:'en', content:'English'}, {value:'de', content:'Deutsch'}, {value:'es', content:'Español'}, {value:'fr', content:'Français'}];
const timezones = [
 {value:'Europe/Moscow',content:'(UTC+03:00) Москва'}, {value:'Europe/Kaliningrad',content:'(UTC+02:00) Калининград'}, {value:'Europe/Samara',content:'(UTC+04:00) Самара'}, {value:'Asia/Yekaterinburg',content:'(UTC+05:00) Екатеринбург'}, {value:'Asia/Novosibirsk',content:'(UTC+07:00) Новосибирск'}, {value:'Asia/Vladivostok',content:'(UTC+10:00) Владивосток'}, {value:'UTC',content:'(UTC+00:00) Всемирное время'}, {value:'Europe/Berlin',content:'Берлин — Europe/Berlin'}, {value:'America/New_York',content:'Нью-Йорк — America/New_York'}, {value:'Asia/Almaty',content:'(UTC+05:00) Алматы'},
];
function Avatar({settings, small = false}: {settings: Settings; small?: boolean}) {
 const initials = settings.name.trim().split(/\\s+/).filter(Boolean).slice(0, 2).map(s => s[0]).join('').toUpperCase() || 'А';
 return <div className={"'`avatar ${small ? '"'avatar-small' : ''}"'`}>{settings.avatar ? <img src={settings.avatar} alt="Аватар профиля"/> : <span>{initials}</span>}</div>;
}
function SectionHeading({icon, title, description}: {icon: IconName; title: string; description?: string}) {
 return <div className="section-heading"><div className="section-icon"><Icon name={icon} size={19}/></div><div><h2>{title}</h2>{description && <p>{description}</p>}</div></div>;
}
export function App() {
