/bin/bash -lc "mkdir -p /tmp/orbit-check && node --input-type=module <<'JS'
import { chromium } from 'playwright';
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1440,height:1100},deviceScaleFactor:1});
page.on('pageerror', e=> console.log('PAGE ERROR:',e.message));
await page.goto('http://localhost:5173');
await page.screenshot({path:'/tmp/orbit-check/desktop.png',fullPage:true});
console.log('Screenshot taken; height:',await page.locator('body').evaluate(el=>el.scrollHeight));
await browser.close();
JS"

